def _check_braces(format_str):
    """Validate that all braces in format_str are properly matched.

    Raises ValueError if there are unmatched or improperly nested braces.
    """
    i = 0
    while i < len(format_str):
        if format_str[i] == '{':
            # Check if it's {{ (escaped brace)
            if i + 1 < len(format_str) and format_str[i+1] == '{':
                i += 2  # skip {{
            else:
                # Look for matching }
                j = format_str.find('}', i+1)
                if j == -1:
                    raise FormatSpecError("Single '}' encountered in format string at position %d" % i)
                # Check for any { between i and j (nested braces not allowed)
                k = format_str.find('{', i+1)
                if k != -1 and k < j:
                    raise FormatSpecError("unexpected '{' in field name")
                i = j + 1
        elif format_str[i] == '}':
            # Check if it's }} (escaped brace)
            if i + 1 < len(format_str) and format_str[i+1] == '}':
                i += 2  # skip }}
            else:
                raise FormatSpecError("Single '{' encountered in format string at position %d" % i)
        else:
            i += 1


# note: {} are handled separately

